100" value="<?= htmlspecialchars((string)$selectedTicket->team) ?>" placeholder="Ex.: Suporte técnico"></label><label>Tags<input name="tags" class="studio-input" maxlength="500" value="<?= htmlspecialchars((string)$selectedTicket->tags) ?>" placeholder="acesso, e-mail, urgente"></label><button class="studio-btn primary" type="submit">Salvar alterações</button></form></section>
