<?php $this->start('scripts')?><script>
const ticketTemplates=<?= json_encode($templatePayload,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP) ?>;document.querySelector('[data-ticket-select-all]')?.addEventListener('change',event=>document.querySelectorAll('[name="ticket_ids[]"]').forEach(input=>input.checked=event.target.checked));document.getElementById('ticket-bulk-form')?.addEventListener('submit',event=>{if(!document.querySelector('[name="ticket_ids[]"]:checked')){event.preventDefault();window.StudioFeedback?.show('Selecione ao menos um chamado.','warning')}});
const composer=document.querySelector('.studio-ticket-composer'),composerText=composer?.querySelector('textarea'),internalInput=composer?.querySelector('[data-ticket-internal]');composer?.querySelectorAll('[data-ticket-mode]').forEach(button=>button.addEventListener('click',()=>{composer.querySelectorAll('[data-ticket-mode]').forEach(item=>item.classList.toggle('active',item===button));const internal=button.dataset.ticketMode==='internal';internalInput.value=internal?'1':'0';composer.classList.toggle('internal-mode',internal);composerText.placeholder=internal?'Registre uma nota visível apenas para a equipe…':'Escreva sua resposta ao cliente…'}));composer?.querySelector('[data-ticket-template]')?.addEventListener('change',event=>{if(event.target.value!=='')composerText.value=ticketTemplates[Number(event.target.value)]?.body||''});
let ticketSeconds=0,ticketTimerRunning=true;const timerText=composer?.querySelector('[data-ticket-timer]'),timeInput=composer?.querySelector('[data-ticket-time]');const renderTicketTimer=()=>{if(!timerText)return;timerText.textContent=[Math.floor(ticketSeconds/3600),Math.floor(ticketSeconds%3600/60),ticketSeconds%60].map(value=>String(value).padStart(2,'0')).join(':');timeInput.value=String(ticketSeconds)};if(composer)setInterval(()=>{if(ticketTimerRunning){ticketSeconds++;renderTicketTimer()}},1000);composer?.querySelector('[data-ticket-timer-toggle]')?.addEventListener('click',event=>{ticketTimerRunning=!ticketTimerRunning;event.currentTarget.querySelector('ion-icon').name=ticketTimerRunning?'pause-outline':'play-outline'});composer?.querySelector('[data-ticket-timer-reset]')?.addEventListener('click',()=>{ticketSeconds=0;renderTicketTimer()});
</script><?php $this->stop()?>
